  // #1368 fixture seams: the run-view Nth-read override (run-<id>.1.json)
  // serves a queued status before the base completed one — the
  // terminal-wait flip.
  bool lsremoteFailFirst = false,
  String? firstViewJson,
  Map<String, String> extraEnv = const {},
}) {
